In the following, let $(H, \dual{\cdot}{\cdot}, \|\cdot \|)$ be a real Hilbert space. Its 
dual space is denoted
by $(H^*, \dual[H^*]{\cdot}{\cdot}, \| \cdot \|_{H^*} )$. 
Since $H$ is a Hilbert space, there exists an isometric isomorphism $\iota \colon 
H^* \to H$ such that $\iota^{-1} \colon H \to H^*$ with $\iota^{-1}: v \mapsto 
\dual{v}{\cdot}$. 
We denote by $\N$ the natural numbers, not including $0$.

Let $(\Omega, \F, \P )$ be a complete probability space and let $\{\xi_n\}_{n \in \N}$ be 
a family of jointly independent random variables on $\Omega$.
For a random variable $X \colon \Omega \to H$, let $\E_{\xi}[X]$ denote the 
expectation with respect to the probability distribution of $\xi$. 
We are mainly interested in the total expectation
\begin{equation*}
  \E_n \big[ \|X\|^2 \big] = \E_{\xi_1}\big[ \E_{\xi_2}\big[ \cdots 
  \E_{\xi_n} \big[ \|X \|^2 \big] \cdots \big]\big].
\end{equation*}
Since the random variables $\{\xi_n\}_{n \in \N}$ are jointly independent, this expectation 
coincides with the expectation with respect to the joint probability distribution of $\xi_1, 
\ldots, \xi_n$. We also note here that if one of the following statements does not involve an expectation but does contain a random variable, then it is assumed to hold almost surely (a.s.) even if this is not explicitly stated.

For a random variable $\xi$ on $\Omega$, we consider the function $f(\xi, \cdot ) \colon 
\Omega \times H \to \R$ such that
\begin{equation*}
  F(w) = \E_{\xi} \big[ f(\xi, w)\big],
\end{equation*}
and aim to find
\begin{equation*}
  w^* = \argmin_{w} F(w).
\end{equation*}
The  existence of such a minimum will be guaranteed by a strong convexity assumption below. We note that this means that $\nabla F(w^*) = 0$.


\begin{assumption} \label{ass:fStoch}
  Let $f(\xi, \cdot ) \colon \Omega \times H \to \R$ be given such that
  \begin{itemize}
    \item $\dual{\iota \nabla f (v)}{w} = \lim_{h \to 0} \frac{f(v + hw) - f(v)}{h}$ a.s. 
      for all $v,w \in H$, i.e., $f$ is G\^{a}teaux differentiable a.s.;
    \item there exists 
      $\mu_{\xi} \colon \Omega \to [0,\infty)$ with $\E_{\xi} [\mu_{\xi}] =: \mu \in (0,\infty)$ 
      such that
      \begin{equation*}
        \dual{\iota \nabla f(\xi,v) - \iota \nabla f(\xi,w)}{v - w} \geq \mu_{\xi} \|v - w\|^2 \quad 
        \text{a.s. for all } v,w \in H;
      \end{equation*}
    \item there exists 
    $L_{\xi} \colon \Omega \to [0,\infty)$ with $\big(\E_{\xi}\big[ L_{\xi}^2 
    \big]\big)^{\frac{1}{2}} =: L \in (0,\infty)$ such that
    \begin{equation*}
      \| \iota \nabla f(\xi, v) - \iota \nabla f(\xi, w) \| \leq L_{\xi} \| v - w\| \quad 
      \text{a.s. for all } v,w \in H;
    \end{equation*}
    \item $\big(\E_{\xi} \big[\| \iota \nabla f(\xi,w^*) \|^2 \big]\big)^{\frac{1}{2}} =: 
    \sigma \in [0,\infty)$.
  \end{itemize}
\end{assumption}

\begin{assumption}\label{ass:fHigherIntegrability}
  Let $f$ be given such that Assumption~\ref{ass:fStoch} is fulfilled. Further, assume that 
  for all $v,w \in H$
  \begin{itemize}
    \item $\dual{\iota \nabla f(\xi,v) - \iota \nabla f(\xi,w)}{v - w} \geq \mu_{\xi} \|v - w\|^2$ 
    with $\big(\E_{\xi} \big[\| \mu_{\xi}^2 \big]\big)^{\frac{1}{2}} =: 
    \mu_2 \in (0,\infty)$.
    \item $ \| \iota \nabla f(\xi, v) - \iota \nabla f(\xi, w) \| \leq L_{\xi} \| v - w\|$ with 
    $\big(\E_{\xi}\big[ L_{\xi}^4 \big]\big)^{\frac{1}{4}} =: L_4 \in (0,\infty)$;
    \item $\big(\E_{\xi} \big[\| \iota \nabla f(\xi,w^*) \|^4 \big]\big)^{\frac{1}{4}} =: 
    \sigma_4 \in [0,\infty)$.
  \end{itemize}
\end{assumption}

Throughout the paper, we will assume that $\{\xi_n\}_{n \in \N}$ is a given a family of 
jointly independent random variables and we will abbreviate $f_n(w) = f(\xi_n,w)$ for $n 
\in \N$. The $\xi_n$ typically correspond to what batches we choose in each iteration, 
i.e.\ on which part of the data we evaluate the gradient.
Let $\{\alpha_n\}_{n \in \N}$ be a sequence of of positive real numbers.
We then consider the stochastic tamed Euler scheme
\begin{align}\label{eq:stochTamedEuler}
  w^{n+1} = w^n - \frac{\alpha_n \iota \nabla f_n(w^n)}{1 + \alpha_n \|\iota 
  \nabla f_n(w^n)\|} \quad \text{for }n \in \N, 
  \quad w^1 = w_1.
\end{align}

Note that it is also possible to choose a random initial value $w^1$, and our convergence statements can be 
extended to this setting in a straightforward way. For simplicity, we restrict ourselves to a fixed initial 
value $w_1 \in H$ in the following.


Given  $z \in H$ and $\alpha > 0$, we define $T_{\alpha f_n, z}(w) \colon \Omega \times 
H \to H$ by
\begin{align*}
  T_{\alpha f_n, z}(w)
  = w - \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \|\iota \nabla f_n(z)\|}.
\end{align*}
This implies that the next iterate $w^{n+1}$ is given by $T_{\alpha_n f_n, w^n}(w^n)$.

