\begin{lemma} \label{lem:Fconsequences}
  Let Assumption~\ref{ass:fStoch} be fulfilled. 
  Then $F$ is strongly convex with convexity constant $\mu$ and $\nabla F$ is Lipschitz 
  continuous with Lipschitz constant $L_F \le L$, i.e.\ for all $v,w \in H$ it holds that
  \begin{align*}
    \| \nabla F(v) - \nabla F(w) \|_{H^*} 
    &= \| \iota \nabla F(v) - \iota \nabla F(w) \| 
    \leq L_F \| v - w\| 
    \leq L \| v - w\| \quad \text{and} \\
    F(v) &\geq F(w) + \dual{\iota \nabla F(w) }{ v - w }+ \frac{\mu}{2} \|v - w\|^2.
  \end{align*}
  Further, the first inequality implies that
  \begin{align*}
    F(v) 
    &\leq F(w)+\dual{\iota \nabla F(w) }{ v - w }+ \frac{L}{2} \|v - w\|^2.
  \end{align*}
  Finally, there exists a unique $w^* \in H$ such that $F(w^*) = \min_{w \in H} F(w)$.
\end{lemma}

\begin{lemma} \label{lem:apriori2}
  Let Assumption~\ref{ass:fStoch} be fulfilled and let $\{\alpha_n\}_{n \in \N}$ be a 
  sequence of positive real numbers such that $\sum_{n =1}^{\infty} \alpha_n^2 < 
  \infty$.
  For $\Phi \in [0,\infty)$ the a priori bound
  \begin{align*}
    &\E_n \big[\|w^{n+1} - w^*\|^2\big] \\
    &\leq \| w_1 - w^*\|^2 \exptextB{ \sum_{i=1}^{\infty} \big(2 \sigma^2 \min\big\{\Phi^{-2}, 
      \alpha_i^2 \big\} + 4 \alpha_i^2 L^2 m_i\big)} \\
    &\quad + \sum_{i=1}^{\infty} \big(\Phi^2 \min \big\{ \E_i \big[ \|\iota \nabla 
    f_i(w^i)\|^{-2} \big], 
    \alpha_i^2 \big\} + 2 ( 1- m_i) + 2 \min \big\{1, 2 \alpha_i^2 \sigma^2 \big\}\big)\\
    &\qquad \times \exptextB{\sum_{j=i+1}^{\infty} \big(2 \sigma^2 \min\big\{\Phi^{-2}, 
      \alpha_j^2 \big\} + 4 \alpha_j^2 L^2 m_j\big)} =: M_2
  \end{align*}
  is fulfilled, where $\min\big\{\Phi^{-2}, x \big\} = x$ for $\Phi = 0$ and every $x \in \R$ 
  and 
  \begin{align*}
    m_i =
    \begin{cases}
      1, & \text{\emph{if }} 2 \alpha_i^2 L^2 \E_{i-1} \big[ \| w^i - w^*\|^2\big] \le 1, \\
      0, & \text{\emph{otherwise}}.
    \end{cases}
  \end{align*}
  Furthermore, there exists $n_0 \in \N$ such that $m_i = 1$ for all $i \geq n_0$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:apriori2}]
  We test the scheme defined by~\eqref{eq:stochTamedEuler}
  with $w^n - w^*$, in order to obtain that
  \begin{align}\label{eq:proofApriori1}
    \begin{split}
      &\dual{w^{n+1} - w^* - (w^n - w^*)}{w^n - w^*} \\
      &\quad + \frac{\alpha_n \dual{\iota \nabla f_n(w^n) - \iota \nabla 
          f_n(w^*)}{w^n - w^*}}{1 
        + \alpha_n \|\iota \nabla f_n(w^n)\|} 
      = - \frac{\alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*}}{1 + \alpha_n \|\iota 
        \nabla f_n(w^n)\|}.
    \end{split}
  \end{align}
  Using the identity $\dual{u-v}{u} = \frac{1}{2} (\|u\|^2 - \|v\|^2 + \|u-v\|^2)$, $u,v \in H$, the 
  first summand on the left-hand side can be written as
  \begin{align*}
    &- \dual{w^n - w^* - (w^{n+1} - w^*)}{w^n - w^*} \\
    &= - \frac{1}{2} \big( \|w^n - w^*\|^2 - \|w^{n+1} - w^*\|^2 + \|w^{n+1} - w^n\|^2 \big)\\
    &= \frac{1}{2} \Big(\|w^{n+1} - w^*\|^2 - \|w^n - w^*\|^2 - \frac{\alpha_n^2 \| \iota 
      \nabla  f_n(w^n)\|^2 }{(1 + \alpha_n \|\iota \nabla f_n(w^n)\|)^2}\Big), 
  \end{align*}
  where we inserted the scheme in the last step. 
  Thus, inserting the monotonicity condition for $f_n$ into 
  \eqref{eq:proofApriori1} and multiplying the inequality with the factor two, it follows that
  \begin{align*}
    &\|w^{n+1} - w^*\|^2 - \|w^n - w^*\|^2 \\
    &\leq - \frac{2\alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*}}{1 + \alpha_n 
      \|\iota \nabla  
      f_n(w^n)\|} 
    + \frac{\alpha_n^2 \| \iota \nabla f_n(w^n)\|^2 }{(1 + \alpha_n \|\iota \nabla  
      f_n(w^n)\|)^2} 
    =: I_1 + I_2.
  \end{align*}
  Since the tamed Euler scheme is the forward Euler scheme with a second order 
  perturbation, it follows that
  \begin{align*}
    \frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \|\iota \nabla  f_n(w^n)\|}
    = \frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \Phi}
    + \frac{ \alpha_n^2 \big(\Phi - \|\iota \nabla f_n(w^n)\|\big) \iota \nabla f_n(w^*) 
    }{(1 + \alpha_n \|\iota \nabla  f_n(w^n)\|) (1 + \alpha_n \Phi )}
  \end{align*}
  for $\Phi \in [0,\infty)$. Note that we have $w^*$ in the numerator of the left-hand-side 
  but $w^n$ in the denominator. We insert this equality into $I_1$ and use the 
  Cauchy--Schwarz inequality and 
  Young's  inequality for products in order to obtain
  \begin{align*}
    I_1 
    &= - \frac{\alpha_n \dual{2 \iota \nabla f_n(w^*)}{w^n - w^*}} {1 + \alpha_n \|\iota \nabla  
      f_n(w^n)\|} \\
    &\leq - \frac{2 \alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*} }{1 + \alpha_n \Phi}
    + \frac{2 \alpha_n^2 \Phi \| \iota \nabla f_n(w^*)\| \| w^n - w^*\| }{(1 + \alpha_n \|\iota 
    \nabla  f_n(w^n)\|) (1 + \alpha_n \Phi )} \\
    &\quad + \frac{2 \alpha_n^2 \|\iota \nabla f_n(w^n)\| \| \iota \nabla f_n(w^*)\| \| w^n - 
    w^*\| }{(1 + \alpha_n \|\iota \nabla  f_n(w^n)\|) (1 + \alpha_n \Phi )} \\
    &\leq - \frac{2 \alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*} }{1 + \alpha_n \Phi}
    + \frac{ \alpha_n^2 \big(\Phi^2 + \|\iota \nabla f_n(w^n)\|^2\big)}{(1 + \alpha_n \|\iota 
    \nabla  f_n(w^n)\|)^2} \\
    &\quad + \frac{2 \alpha_n^2 \| \iota \nabla f_n(w^*)\|^2 \| w^n - w^*\|^2 }{(1 + \alpha_n 
    \Phi )^2}
    =: I_{1,1} + I_{1,2} + I_{1,3}.
  \end{align*}
  For $I_{1,1} = - \frac{2 \alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*} }{1 + \alpha_n 
  \Phi}$, we notice that $\E_{\xi_n} [I_{1,1}] = 0$. Moreover, for $I_{1,2} = \frac{\alpha_n^2 
  ( 
  \Phi^2 + \|\iota \nabla f_n(w^n)\|^2 )}{(1 + \alpha_n \|\iota \nabla f_n(w^n)\|)^2}$, we get
  \begin{align*}
    I_{1,2}
    &\leq \Phi^2 \min \big\{ \|\iota \nabla f_n(w^n)\|^{-2} , \alpha_n^2 \big\}
    + \min \big\{1, \alpha_n^2 \|\iota \nabla f_n(w^n)\|^2 \big\} \\
    &\leq \Phi^2 \min \big\{ \|\iota \nabla f_n(w^n)\|^{-2} , \alpha_n^2 \big\}
    + \min \big\{1, 2 \alpha_n^2 L_{\xi_n}^2 \|w^n - w^*\|^2\big\}\\ 
    &\quad + \min \big\{1,2 \alpha_n^2 \|\iota \nabla f_n(w^*)\|^2 \big\}
  \end{align*}
  and
  \begin{align*}
    I_{1,3}
    = \frac{2\alpha_n^2 \|\iota \nabla f_n(w^*)\|^2 \|w^n - w^*\|^2}{(1 + \alpha_n \Phi )^2}
    \leq 2 \|\iota \nabla f_n(w^*)\|^2 \min \big\{\Phi^{-2}, \alpha_n^2 \big\} \|w^n - w^*\|^2.
  \end{align*}
  A bound for $I_2$ is given by
  \begin{align*}
    I_2 &= \frac{\alpha_n^2 \| \iota \nabla f_n(w^n)\|^2 }{(1 + \alpha_n \|\iota \nabla 
    f_n(w^n)\| )^2}
    \leq \min \big\{1, \alpha_n^2 \| \iota \nabla f_n(w^n)\|^2 \big\}\\
    &\leq \min \big\{1, 2 \alpha_n^2 L_{\xi_n}^2 \| w^n - w^*\|^2 \big\}
    + \min \big\{1, 2 \alpha_n^2 \|\iota \nabla f_n(w^*)\|^2 \big\}.
  \end{align*}  
  Then it follows
  \begin{align}
    \label{eq:aprioriBoundMn}
    \begin{split}
      &\|w^{n+1} - w^*\|^2 - \|w^n - w^*\|^2 \leq  I_1 + I_2\\
      &\leq - \frac{2 \alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - w^*} }{1 + \alpha_n \Phi}
      + \Phi^2 \min \big\{ \|\iota \nabla f_n(w^n)\|^{-2} , \alpha_n^2 \big\}\\
      &\quad + 2 \min \big\{1, 2 \alpha_n^2 L_{\xi_n}^2 \|w^n - w^*\|^2\big\} + 2 \min 
      \big\{1,2 \alpha_n^2 \|\iota \nabla f_n(w^*)\|^2 \big\}\\
      &\quad + 2 \|\iota \nabla f_n(w^*)\|^2 \min \big\{\Phi^{-2}, \alpha_n^2 \big\} \|w^n - 
      w^*\|^2.
    \end{split}
  \end{align}
  Taking the $\E_n$-expectation, we then obtain
  \begin{equation}
    \label{eq:aprioriBoundMnExp}
    \begin{aligned}
      &\E_n \big[\|w^{n+1} - w^*\|^2\big] \\
      &\quad \leq \big(1 + 2 \sigma^2 \min\big\{ \Phi^{-2}, \alpha_n^2 \big\} \big) \E_{n-1} 
      \big[ 
      \|w^n - w^*\|^2 \big]\\
      &\qquad + \Phi^2 \min \big\{ \E_n \big[\|\iota \nabla f_n(w^n)\|^{-2}\big], \alpha_n^2 
      \big\}\\
      &\qquad + 2 \min \big\{1, 2 \alpha_n^2 L^2 \E_{n-1} \big[ \|w^n - w^*\|^2 \big]\big\} 
      + 2 \min \big\{1,2 \alpha_n^2 \sigma^2\big\}\\
      &\quad= \big(1 + 2 \min\big\{ \Phi^{-2}, \alpha_n^2 \big\} \sigma^2+ 4 \alpha_n^2 L^2 
      m_n\big) \E_{n-1} \big[ \|w^n - w^*\|^2 \big]\\
      &\qquad + \Phi^2 \min \big\{ \E_n \big[\|\iota \nabla f_n(w^n)\|^{-2}\big], 
      \alpha_n^2 \big\}
      + 2 (1-m_n) 
      + 2 \min \big\{1,2 \alpha_n^2 \sigma^2\big\},
    \end{aligned}
  \end{equation}
  with $m_n$ defined as in the lemma statement. Reinserting the bound 
  repeatedly thus yields
  \begin{align*}
    &\E_n \big[\|w^{n+1} - w^*\|^2\big] \\
    &\leq \| w_1 - w^*\|^2 \prod_{i=1}^{n} \big(1 + 2 \sigma^2 \min\big\{\Phi^{-2}, 
    \alpha_i^2 \big\} + 4 \alpha_i^2 L^2 m_i\big) \\
    &\quad + \sum_{i=1}^{n} \big(\Phi^2 \min \big\{ \E_i \big[ \|\iota \nabla 
    f_i(w^i)\|^{-2} \big], 
    \alpha_i^2 \big\} + 2 ( 1- m_i) + 2 \min \big\{1, 2 \alpha_i^2 \sigma^2 \big\}\big)\\
    &\qquad \times \prod_{j=i+1}^{n} \big(1 + 2 \sigma^2 \min\big\{\Phi^{-2}, 
    \alpha_j^2 \big\} + 4 \alpha_j^2 L^2 m_j\big).
  \end{align*}
  Finally, we apply the inequality $1 + x \leq \exptext{x}$, $x \in \R$, and make 
  the bound independent of $n$ by bounding the final sums by the corresponding infinite 
  sums, in order to obtain
  \begin{align*}
    &\E_n \big[\|w^{n+1} - w^*\|^2\big] \\
    &\leq \| w_1 - w^*\|^2 \exptextB{ \sum_{i=1}^{\infty} \big(2 \sigma^2 \min\big\{\Phi^{-2}, 
      \alpha_i^2 \big\} + 4 \alpha_i^2 L^2 m_i\big)} \\
    &\quad + \sum_{i=1}^{\infty} \big(\Phi^2 \min \big\{ \E_i \big[ \|\iota \nabla 
    f_i(w^i)\|^{-2} \big], 
    \alpha_i^2 \big\} + 2 ( 1- m_i) + 2 \min \big\{1, 2 \alpha_i^2 \sigma^2 \big\}\big)\\
    &\qquad \times \exptextB{\sum_{j=i+1}^{\infty} \big(2 \sigma^2 \min\big\{\Phi^{-2}, 
      \alpha_j^2 \big\} + 4 \alpha_j^2 L^2 m_j\big)}.
  \end{align*}
  It remains to verify, that there exists $n_0 \in \N$ such that $m_n = 1$ for all $n \geq 
  n_0$. This can be done by estimating \eqref{eq:aprioriBoundMnExp} and following a 
  similar line of argumentation as before. First, we can write
  \begin{align*}
    \E_n \big[\|w^{n+1} - w^*\|^2\big] 
    \leq \big(1 + 2 \alpha_n^2 \sigma^2 + 4 \alpha_n^2 L^2 \big) \E_{n-1} \big[ \|w^n - 
    w^*\|^2\big] + \Phi^2 \alpha_n^2 + 4 \alpha_n^2 \sigma^2.
  \end{align*}
  Reinserting the inequality $n -1$ times, it follows that
  \begin{align*}
    &\E_n \big[\|w^{n+1} - w^*\|^2\big] \\
    &\leq \| w_1 - w^*\|^2 \prod_{i=1}^{n} \big(1 + 2 \sigma^2 \alpha_i^2 + 4 \alpha_i^2 L^2 
    \big) 
    + \sum_{i=1}^{n} 4 \alpha_i^2 \sigma^2 \prod_{j=i+1}^{n} \big(1 + 2 \sigma^2 
    \alpha_j^2 + 4 \alpha_j^2 L^2 \big)\\
    &\leq \| w_1 - w^*\|^2 \exptextB{ \big(2 \sigma^2 + 4 L^2 \big) \sum_{i=1}^{\infty} 
    \alpha_i^2 }
    + \sum_{i=1}^{\infty} 4 \alpha_i^2 \sigma^2 \exptextB{ \big(2 \sigma^2 + 4 L^2 \big) 
    \sum_{j=i+1}^{\infty} \alpha_j^2 }.
  \end{align*}
  Since $\sum_{n =1}^{\infty} \alpha_n^2 < \infty$ there is thus a $n_0 \in \N$ such that $2 \alpha_n^2 L^2 \E_{n-1} \big[ \| w^n - w^*\|^2\big] \leq 1$ for all $n \geq n_0$.
\end{proof}

\begin{proof}
  Within the proof of Lemma~\ref{lem:apriori2}, we verified the inequality 
  \eqref{eq:aprioriBoundMn}. Starting from this point, we find
  \begin{equation}
    \label{eq:apriori4}
    \|w^{n+1} - w^*\|^2 - \|w^n - w^*\|^2 \leq A_n + B_n,
  \end{equation}
  where
  \begin{align*}
    A_n &= -\frac{2 \alpha_n \dual{\iota \nabla f_n(w^*)}{w^n - 
    w^*} }{1 + \alpha_n \Phi} \qquad \text{and} \\
    B_n &= \Phi^2 \min \big\{ \|\iota \nabla f_n(w^n)\|^{-2} , \alpha_n^2 \big\}
     + 2 \min \big\{1, 2 \alpha_n^2 L_{\xi_n}^2 \|w^n - w^*\|^2\big\}\\
      &\quad + 2 \min \big\{1,2 \alpha_n^2 \|\iota \nabla f_n(w^*)\|^2 \big\}
      + 2 \|\iota \nabla f_n(w^*)\|^2 \min \big\{\Phi^{-2}, \alpha_n^2 \big\} \|w^n - w^*\|^2 
  \end{align*}
  for $\Phi \in [0,\infty)$. We note that the parameter $\Phi$ can be chosen such that 
  $\E_n[B_n]$ is as small as possible.
  From this it follows that 
  \begin{align*}
    \E_{\xi_n} [A_n] &= 0,\\
    \E_{\xi_n} [B_n] &\leq  \Phi^2 \min \big\{ \E_{\xi_n} \big[ \|\iota \nabla f_n(w^n)\|^{-2}\big] 
    , 
    \alpha_n^2 \big\}
    + 2 \min \big\{1, 2 \alpha_n^2 L^2 \|w^n - w^*\|^2\big\}\\
    &\quad + 2 \min \big\{1,2 \alpha_n^2 \sigma^2 \big\}
    + 2 \sigma^2 \min \big\{\Phi^{-2}, \alpha_n^2 \big\} \|w^n - w^*\|^2, \\
    \E_{\xi_n} [A_n^2] 
    &\leq 4 \sigma^2 \min\{ \Phi^{-2}, \alpha_n^2 \} \| w^n - w^*\|^2 \qquad \text{and}\\
    \E_{\xi_n} [B_n^2] 
    &\leq 4 \Phi^4 \min \big\{ \big(\E_{\xi_n} \big[ \|\iota \nabla f_n(w^n)\|^{-2}\big]\big)^2 , 
    \alpha_n^4 \big\}
    + 16 \min \big\{1, 4 \alpha_n^4 L_4^4 \|w^n - w^*\|^4\big\}\\
    &\quad + 16 \min \big\{1,4 \alpha_n^4 \sigma_4^4 \big\}
    + 16  \sigma_4^4 \min \big\{\Phi^{-4}, \alpha_n^4 \big\} \|w^n - w^*\|^4.
  \end{align*}
   We note that for $a,b \in \R$ we have the identity $(a - b)a = \frac{1}{2} \big( |a|^2 - |b|^2 
   + |a - b|^2 \big)$, and thus $|a|^2 - |b|^2 \le 2(a-b)a$. By multiplying the inequality from 
   \eqref{eq:apriori4} with the factor $2\|w^{n+1} - w^*\|^2$, we therefore obtain
  \begin{align*}
    \|w^{n+1} - w^*\|^4 - \|w^n - w^*\|^4
    &\leq 2\big( A_n + B_n \big) \|w^{n+1} - w^*\|^2\\
    &\leq 2\big( A_n + B_n \big) \big( \|w^n - w^*\|^2 + A_n + B_n  \big)\\
    &\leq 2(A_n + B_n) \|w^n - w^*\|^2  + 4 A_n^2 + 4 B_n^2 
  \end{align*}
  and in $\E_{\xi_n}$-expectation
  \begin{align*}
    & \E_{\xi_n} \big[ \|w^{n+1} - w^*\|^4\big] - \|w^n - w^*\|^4\\
    &\leq 4 \Big(2 L^2 \min \big\{\tfrac{1}{2} L^{-2} \|w^n - w^*\|^{-2}, \alpha_n^2 \big\}
    + \sigma^2 \min \big\{\Phi^{-2}, \alpha_n^2 \big\}\\
    &\qquad + 64 L_4^4 \min \big\{ \tfrac{1}{4} L_4^{-4} \|w^n - w^*\|^{-4}, \alpha_n^4 
    \big\} + 16 \sigma_4^4 \min \big\{\Phi^{-4}, \alpha_n^4 \big\} \Big)\|w^n - w^*\|^4 \\
    &\quad + 2 \Big( \Phi^2 \min \big\{ \E_{\xi_n} \big[ \|\iota \nabla f_n(w^n)\|^{-2}\big] , 
    \alpha_n^2 \big\} 
    + 4 \sigma^2\min \big\{\tfrac{1}{2} \sigma^{-2} , \alpha_n^2 \big\} \\
    &\qquad + 8  \sigma^2 \min\{ \Phi^{-2}, \alpha_n^2 \} \Big) \|w^n - w^*\|^2 \\
    &\quad + 16 \Phi^4 \min \big\{ \big(\E_{\xi_n} \big[ \|\iota \nabla 
    f_n(w^n)\|^{-2}\big]\big)^2 
    , \alpha_n^4 \big\}
    + 256 \sigma_4^4 \min \big\{ \tfrac{1}{4}\sigma_4^{-4},\alpha_n^4 \big\}\\
    %
    &=: c_1^n (\alpha_n) \|w^n - w^*\|^4 + c_2^n(\alpha_n) \|w^n - w^*\|^2 
    + c_3^n(\alpha_n).
  \end{align*}
  Adding $\|w^n - w^*\|^4$ to both sides of the inequality, taking the 
  $\E_{n-1}$-expectation and reinserting the bound, we obtain
  \begin{align*}
    & \E_n \big[ \|w^{n+1} - w^*\|^4\big] \\
    &\leq \big(1 + c_1^n(\alpha_n) \big) \E_{n-1} \big[ \|w^n - w^*\|^4 \big]
    + c_2^n(\alpha_n) M_2 + c_3^n(\alpha_n)\\
    &\leq \|w^1 - w^*\|^4 \prod_{i = 1}^{n} \big(1 + c_1^i(\alpha_i) \big) 
    + \sum_{i=1}^{n} \big(c_2^i(\alpha_i) M_2 + c_3^i(\alpha_i)\big) \prod_{j = i+ 
    1}^{n} \big(1 + c_1^j(\alpha_j) \big) \\
    &\leq \|w^1 - w^*\|^4 \exptextB{\sum_{i = 1}^{\infty} c_1^i(\alpha_i) } 
    + \sum_{i=1}^{\infty} \big(c_2^i(\alpha_i) M_2 + c_3^i(\alpha_i)\big) 
    \exptextB{\sum_{j = i+ 1}^{\infty} c_1^j(\alpha_j)} .
  \end{align*}
  Finally, this is finite due to the assumption $\sum_{n  =1}^{\infty} \alpha_n^2 < \infty$.
\end{proof}

\begin{lemma}\label{lem:SecondLipT}
  Let Assumption~\ref{ass:fStoch} be fulfilled and let $z \in H$, $\alpha 
  \in (0,\infty)$ and $\Xi \in [0,\infty)$ be given.
  It then follows that
  \begin{align*}
    \Big\| T_{\alpha f_n, z}(w) - w + \frac{\alpha 
      \iota \nabla f_n(w)}{1 + \alpha \Xi} \Big\|
    = \frac{ \alpha^2 \big| \Xi - \|\iota \nabla f_n(z)\|\big| \|\iota \nabla f_n(w)\|}
    {(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )}
  \end{align*}
  for all $w \in H$.
\end{lemma}

\begin{proof}
  Inserting the definition of $T_{\alpha f_n, z}$, it follows that
  \begin{align*}
    &\Big\| T_{\alpha f_n, z}(w) - w + \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha 
    \Xi} \Big\|
  = \Big\| \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \|\iota \nabla f_n(z)\|} - 
    \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \Xi } \Big\|\\
    &= \Big\| \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \Xi \iota \nabla f_n(w) 
    }{(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )}
    - \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \|\iota \nabla f_n(z)\| \iota \nabla 
    f_n(w) }{ (1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi ) } \Big\|\\
    &= \frac{ \alpha^2 \big| \Xi - \|\iota \nabla f_n(z)\|\big| \|\iota \nabla f_n(w)\|}
    {(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )},
  \end{align*}
  for all $w \in H$, which proves the claim.
\end{proof}

\begin{proof}
  From $w^{n+1} = T_{\alpha_n f_n, w^n}(w^n)$ we obtain that
  \begin{align*}
    \| w^{n+1} - w^* \|^2
    &= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*) + T_{\alpha_n f_n, 
      w^n}(w^*) - w^*\|^2\\
    &= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)\|^2 + \|T_{\alpha_n f_n, 
      w^n}(w^*) - w^*\|^2\\
    &\quad + 2 \dual{T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)}{T_{\alpha_n 
        f_n, w^n}(w^*) - w^*}\\
    &=: I_1 + I_2 + 2 I_3.
  \end{align*}
  For $I_1$, we can write
  \begin{align*}
    I_1&= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)\|^2\\
    &= \big\| w^n - w^* + (T_{\alpha_n f_n, w^n} - I)(w^n) -
    (T_{\alpha_n f_n, w^n} - I)(w^*)\big\|^2\\
    &= \| w^n - w^*\|^2
    + 2 \dualb{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) } 
    \\
    &\quad + \| (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) \|^2
    =: I_{1,1} + 2I_{1,2} + I_{1,3}.
  \end{align*}
  The term $I_{1,2}$ can be estimated by applying the Cauchy--Schwarz inequality:
  \begin{align*}
    I_{1,2}&= \dualb{w^n - w^*}{ (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - 
      I)(w^*) }\\
    &= - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^n)}{1 + \alpha_n \|\iota 
    \nabla f_n(w^n)\|} 
      - \frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \|\iota \nabla f_n(w^n)\|}}\\
    &\leq - \frac{\alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } \|w^n - 
    w^*\|^2.
  \end{align*}
  For $I_{1,3}$, we insert the definition of $T_{\alpha_n f_n, w^n}$ and find
  \begin{align*}
    I_{1,3} 
    &= \| (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) \|^2\\
    &=  \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
    \|\iota \nabla f_n(w^n)\| )^2}.
  \end{align*}
  Thus, for $I_1$, we have
  \begin{align*}
    I_1
    \leq \Big( 1 - \frac{2 \alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } 
    \Big)\| w^n - w^*\|^2
    + \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
      \|\iota \nabla f_n(w^n)\| )^2}.
  \end{align*}
  Further, $I_2$ can be written as
  \begin{align*}
    I_2
    = \|T_{\alpha_n f_n, w^n}(w^*) - w^*\|^2
    = \frac{\alpha_n^2 \|\iota \nabla f_n (w^*)\|^2 }{( 1 + \alpha_n \|\iota \nabla 
      f_n(w^n)\| )^2}.
  \end{align*}
  Finally, $I_3$ can be rewritten as
  \begin{align*}
    I_3 &= \dual{T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)}{T_{\alpha_n f_n, 
        w^n}(w^*) - w^*}\\
    &= \dual{(T_{\alpha_n f_n, w^n} - I) (w^n) - (T_{\alpha_n f_n, w^n} - I) 
      (w^*)}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &\quad + \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}
    =: I_{3,1} + I_{3,2}.
  \end{align*}
  Then for $I_{3,1}$, we insert the definition of $T_{\alpha_n f_n, w^n}$ and obtain
  \begin{align*}
    I_{3,1} &= \dual{(T_{\alpha_n f_n, w^n} - I) (w^n) - (T_{\alpha_n f_n, w^n} - I) 
      (w^*)}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &\leq \frac{\alpha_n \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|}{1 + \alpha_n \|\iota 
    \nabla f_n(w^n)\|} \cdot
    \frac{\alpha_n \| \iota \nabla f_n (w^*)\|}{1 + \alpha_n \|\iota \nabla f_n(w^n)\|} \\
    &\leq \frac{1}{2}\frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2}{ (1 + 
    \alpha_n \|\iota \nabla f_n(w^n)\| )^2} 
    + \frac{1}{2} \frac{\alpha_n^2 \| \iota \nabla f_n (w^*)\|^2}{(1 + \alpha_n \|\iota 
      \nabla f_n(w^n)\| )^2},
  \end{align*}
  where we applied the Cauchy--Schwarz inequality and Young's inequality.
  To estimate $I_{3,2}$, we add and subtract an additional summand, so that
  \begin{align*}
    I_{3,2} &= \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &= \dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
    f_n(w^*)}{1 + \alpha_n \Xi }}
    - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \Xi }},
  \end{align*}
  where $\E_{\xi_n}\big[ \dualb{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 
  + \alpha_n \Xi }} \big] = 0$ is fulfilled. Moreover, applying 
  Lemma~\ref{lem:SecondLipT} and the Cauchy--Schwarz inequality, we obtain
  \begin{align*}
    &\dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
        f_n(w^*)}{1 + \alpha_n \Xi }}\\
    &\leq \frac{ \alpha_n^2 \big|\Xi - \|\iota \nabla f_n(w^n)\| \big| \|\iota \nabla f_n(w^*)\|}
    {(1 + \alpha_n \|\iota \nabla f_n(w^n)\| ) (1 + \alpha_n \Xi )}  \| w^n 
    - w^* \|.
  \end{align*}
  Thus, the expectation of $I_3 = I_{3,1} + I_{3,2}$ can be bounded by
  \begin{align*}
    \E_{\xi_n} [I_3 ]
    &\leq \frac{1}{2} \E_{\xi_n} \Big[ \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla 
    f_n(w^*)\|^2 }{\big(1 + \alpha_n \|\iota \nabla 
      f_n(w^n)\|\big)^2} + \frac{\alpha_n^2 \| \iota \nabla f_n 
      (w^*)\|^2}{ (1 + \alpha_n \|\iota \nabla f_n(w^n)\| )^2}\Big]\\
    &\quad + \E_{\xi_n} \Big[ \frac{ \alpha_n^2 \big| \Xi - \|\iota \nabla f_n(w^n)\| \big| \|\iota 
    \nabla f_n(w^*)\| }
    {(1 + \alpha_n \|\iota \nabla f_n(w^n)\| ) (1 + \alpha_n \Xi )}\Big]  \| w^n - w^* \| .
  \end{align*}
  Inserting the bounds for $I_1$, $I_2$ and $I_3$ into $\E_{\xi_n} \big[\| w^{n+1} - w^* 
  \|^2\big] = \E_{\xi_n} \big[ I_1 + I_2 + 2 I_3\big]$ finishes the proof.
\end{proof}

\begin{proof}
  In this proof, we apply the following basic inequalities involving (generalized) 
  harmonic numbers
  \begin{align*}
    \sum_{i=m}^n (i+y)^{-1} &\geq \ln{(n+1+y)} - \ln{(m+y)}, 
    \quad m \in \{1,\dots,n\},\\
    \sum_{i=1}^n{ (i+y)^{p}}
    &\leq 
    \begin{cases}
      \frac{(n+1+y)^{p+1}}{p+1}, &p \in [0,\infty) ,\\
      \frac{(n+y)^{p+1}}{p+1}, &p \in (-1,0),\\
      1 + \ln{(n+y)}, &p = -1,\\
      \frac{(1+y)^{p}(p-y)}{p+1}, &p \in (-\infty,-1),
    \end{cases}
  \end{align*}
  for $y \in (0,\infty)$.
  These inequalities follow by treating the sums as a lower or upper Riemann 
  sums approximating the integral $\int {(u+y)^p \diff{u}}$ over the intervals $[0,n]$, $[1,n]$ 
  or $[0,n+1]$. 

  Using the inequality $1 + u \le \exp{u}$ for $u \in [-1, \infty)$, it follows that $0\leq 
  1-\frac{x}{i + y} \le \exptext{-\frac{x}{i+y}}$ is fulfilled for every $i \in \N$ since 
  $\frac{x}{1+y} \leq 1$. It then follows that
  \begin{align*}
    \prod_{i= m}^n \Big(1- \frac{x }{i + y}\Big) 
    &\leq \exptextB{- x \sum_{i=m}^{n} (i + y)^{-1}} \\
    &\leq \exptextb{- x \big(\ln{(n+1+y)} - \ln(m+y)\big)} \\
    &= \exptextB{- x \ln{\Big(\frac{n+1+y}{m+y} \Big)} } 
    = \Big(\frac{n+1+y}{m+y} \Big)^{-x}
  \end{align*}
  from which the first claim follows directly. 
  For the second claim, we use the fact that $\frac{i+1+y}{i+y} = 1 + \frac{1}{i+y} \leq  1 + 
  \frac{1}{1+y}
  \leq \exptext{\frac{1}{1+y}}$ for all $i \in \N$ and find that
  \begin{align*}
    &\sum_{i=1}^n \frac{1}{(i+y)^2} \prod_{j = i+1}^n \Big(1-\frac{x}{j+y} 
    \Big)
    \le \sum_{i=1}^n { \frac{1}{(i+y)^2} \Big(\frac{n+1+y}{i+1+y}\Big)^{-x} } \\
    &\le (n+1+y)^{-x} \sum_{i=1}^n{ \Big(\frac{i+1+y}{i+y}\Big)^{x} (i+y)^{x-2} }\\
    &\le  \exptextB{\frac{x}{1+y}} (n+1+y)^{-x} 
    \sum_{i=1}^n{ (i+y)^{x-2} }\\
    &\leq \exptextB{\frac{x}{1+y}}
    \begin{cases}
      (n+1+y)^{-1}\frac{1}{x-1}, &x \in (1,\infty) ,\\
      (n+1+y)^{-1} \big(1 + \ln{(n+y)}\big), &x = 1,\\
      (n+1+y)^{-x}\frac{(1+y)^{x-2}(x-2-y)}{x-1}, 
      &x \in [0,1),
    \end{cases}
  \end{align*}
  where we applied the basic inequalities from the beginning of the proof.
\end{proof}

\begin{lemma} \label{lem:TaylorEx}
  Given $a,b \in (0,\infty)$, $\frac{-1}{a x + b} \leq - \frac{1}{b} + \frac{a}{b^2} 
  x$ for every $x \in (0,\infty)$. 
\end{lemma}

\begin{proof}
  We consider the function $f \colon [0,\infty) \to \R$ with $f(x) = \frac{-1}{a x + b}$. 
  Then the first and second derivative of $f$ are given by $f'(x) = \frac{a}{(a x + b)^2}$ and 
  $f''(x) = \frac{-2a^2}{(a x + b)^3}$. Using a first-order Taylor expansion of $f$ then shows 
  that
  \begin{align*}
    f(x) = - \frac{1}{b} + \frac{a}{b^2} x - \frac{a^2}{(a \xi + b)^3} x^2
    \leq - \frac{1}{b} + \frac{a}{b^2} x,
  \end{align*}
  where $\xi \in (0,x)$. 
\end{proof}

\begin{lemma} \label{lem:swap_diff_and_expectation}
  Let Assumption~\ref{ass:fStoch} be fulfilled.
  Then $F = \E_{\xi}[f(\xi, \cdot)]$ is G\^{a}teaux differentiable and its derivative is 
  given by
  \begin{align*}
    \dual{\iota \nabla F (v)}{w} = \E_{\xi}[\dual{\iota \nabla f (\xi, v)}{w}].
  \end{align*}
\end{lemma}

\begin{proof}
  See e.g.~\cite[Lemma 6]{RyuBoyd.2016}.
\end{proof}

