\begin{theorem}\label{thm:ConvNorm1}
  Let Assumption~\ref{ass:fHigherIntegrability} be fulfilled.
  For $\alpha_n = \frac{\vartheta}{n + \gamma}$, $n \in \N$, with $\gamma \in [0,\infty)$, 
  $\vartheta \in (0,\frac{1 + \gamma}{2\mu}]$ and
  \begin{align*}
    K = 2 \vartheta^2 L \mu_2 M_4^{\frac{3}{4}} 
    + \big(2 \vartheta^2 L^2 + 2 \vartheta^2 L \sigma + 2 \vartheta^2 \mu_2 \sigma 
    \big) M_2
    + 2 \vartheta^2 \sigma^2 M_2^{\frac{1}{2}} + 2 \vartheta^2 \sigma^2,
  \end{align*}
  it follows that
  \begin{align*}
    &\E_n \big[\| w^{n+1} - w^* \|^2\big]\\
    &\leq \| w_1 - w^*\|^2 (1+\gamma)^{2 \vartheta \mu}(n+1+\gamma)^{-2 \vartheta \mu} \\
    &\quad + \exptextB{\frac{2 \vartheta \mu}{1+\gamma}} K \begin{cases}
      (n+1+\gamma)^{-1} \frac{1}{2 \vartheta \mu-1}, &2 \vartheta \mu \in (1,\infty),\\
      (n+1+\gamma)^{-1} (1 + \ln{(n + \gamma)}), &2 \vartheta \mu = 1,\\
      (n+1+\gamma)^{-2 \vartheta \mu} \frac{(1+\gamma)^{2 \vartheta \mu-2}(2 \vartheta 
      \mu-2-\gamma)}{2 \vartheta \mu-1}, &2 \vartheta \mu \in [0,1),
    \end{cases}
  \end{align*}
  for every $n \in \N$.
\end{theorem}

For a random variable $\xi$ on $\Omega$, we consider the function $f(\xi, \cdot ) \colon 
\Omega \times H \to \R$ such that
\begin{equation*}
  F(w) = \E_{\xi} \big[ f(\xi, w)\big],
\end{equation*}
and aim to find
\begin{equation*}
  w^* = \argmin_{w} F(w).
\end{equation*}
The  existence of such a minimum will be guaranteed by a strong convexity assumption below. We note that this means that $\nabla F(w^*) = 0$.

\begin{assumption} \label{ass:fStoch}
  Let $f(\xi, \cdot ) \colon \Omega \times H \to \R$ be given such that
  \begin{itemize}
    \item $\dual{\iota \nabla f (v)}{w} = \lim_{h \to 0} \frac{f(v + hw) - f(v)}{h}$ a.s. 
      for all $v,w \in H$, i.e., $f$ is G\^{a}teaux differentiable a.s.;
    \item there exists 
      $\mu_{\xi} \colon \Omega \to [0,\infty)$ with $\E_{\xi} [\mu_{\xi}] =: \mu \in (0,\infty)$ 
      such that
      \begin{equation*}
        \dual{\iota \nabla f(\xi,v) - \iota \nabla f(\xi,w)}{v - w} \geq \mu_{\xi} \|v - w\|^2 \quad 
        \text{a.s. for all } v,w \in H;
      \end{equation*}
    \item there exists 
    $L_{\xi} \colon \Omega \to [0,\infty)$ with $\big(\E_{\xi}\big[ L_{\xi}^2 
    \big]\big)^{\frac{1}{2}} =: L \in (0,\infty)$ such that
    \begin{equation*}
      \| \iota \nabla f(\xi, v) - \iota \nabla f(\xi, w) \| \leq L_{\xi} \| v - w\| \quad 
      \text{a.s. for all } v,w \in H;
