\begin{lemma}\label{lem:SecondLipT}
  Let Assumption~\ref{ass:fStoch} be fulfilled and let $z \in H$, $\alpha 
  \in (0,\infty)$ and $\Xi \in [0,\infty)$ be given.
  It then follows that
  \begin{align*}
    \Big\| T_{\alpha f_n, z}(w) - w + \frac{\alpha 
      \iota \nabla f_n(w)}{1 + \alpha \Xi} \Big\|
    = \frac{ \alpha^2 \big| \Xi - \|\iota \nabla f_n(z)\|\big| \|\iota \nabla f_n(w)\|}
    {(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )}
  \end{align*}
  for all $w \in H$.
\end{lemma}

\begin{proof}
  Inserting the definition of $T_{\alpha f_n, z}$, it follows that
  \begin{align*}
    &\Big\| T_{\alpha f_n, z}(w) - w + \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha 
    \Xi} \Big\|
  = \Big\| \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \|\iota \nabla f_n(z)\|} - 
    \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \Xi } \Big\|\\
    &= \Big\| \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \Xi \iota \nabla f_n(w) 
    }{(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )}
    - \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \|\iota \nabla f_n(z)\| \iota \nabla 
    f_n(w) }{ (1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi ) } \Big\|\\
    &= \frac{ \alpha^2 \big| \Xi - \|\iota \nabla f_n(z)\|\big| \|\iota \nabla f_n(w)\|}
    {(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )},
  \end{align*}
  for all $w \in H$, which proves the claim.
\end{proof}

\begin{proof}
  Inserting the definition of $T_{\alpha f_n, z}$, it follows that
  \begin{align*}
    &\Big\| T_{\alpha f_n, z}(w) - w + \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha 
    \Xi} \Big\|
  = \Big\| \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \|\iota \nabla f_n(z)\|} - 
    \frac{\alpha \iota \nabla f_n(w)}{1 + \alpha \Xi } \Big\|\\
    &= \Big\| \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \Xi \iota \nabla f_n(w) 
    }{(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )}
    - \frac{\alpha \iota \nabla f_n(w) + \alpha^2 \|\iota \nabla f_n(z)\| \iota \nabla 
    f_n(w) }{ (1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi ) } \Big\|\\
    &= \frac{ \alpha^2 \big| \Xi - \|\iota \nabla f_n(z)\|\big| \|\iota \nabla f_n(w)\|}
    {(1 + \alpha \|\iota \nabla f_n(z)\| ) (1 + \alpha \Xi )},
  \end{align*}
  for all $w \in H$, which proves the claim.
\end{proof}

\begin{proof}
  From $w^{n+1} = T_{\alpha_n f_n, w^n}(w^n)$ we obtain that
  \begin{align*}
    \| w^{n+1} - w^* \|^2
    &= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*) + T_{\alpha_n f_n, 
      w^n}(w^*) - w^*\|^2\\
    &= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)\|^2 + \|T_{\alpha_n f_n, 
      w^n}(w^*) - w^*\|^2\\
    &\quad + 2 \dual{T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)}{T_{\alpha_n 
        f_n, w^n}(w^*) - w^*}\\
    &=: I_1 + I_2 + 2 I_3.
  \end{align*}
  For $I_1$, we can write
  \begin{align*}
    I_1&= \| T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)\|^2\\
    &= \big\| w^n - w^* + (T_{\alpha_n f_n, w^n} - I)(w^n) -
    (T_{\alpha_n f_n, w^n} - I)(w^*)\big\|^2\\
    &= \| w^n - w^*\|^2
    + 2 \dualb{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) } 
    \\
    &\quad + \| (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) \|^2
    =: I_{1,1} + 2I_{1,2} + I_{1,3}.
  \end{align*}
  The term $I_{1,2}$ can be estimated by applying the Cauchy--Schwarz inequality:
  \begin{align*}
    I_{1,2}&= \dualb{w^n - w^*}{ (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - 
      I)(w^*) }\\
    &= - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^n)}{1 + \alpha_n \|\iota 
    \nabla f_n(w^n)\|} 
      - \frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \|\iota \nabla f_n(w^n)\|}}\\
    &\leq - \frac{\alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } \|w^n - 
    w^*\|^2.
  \end{align*}
  For $I_{1,3}$, we insert the definition of $T_{\alpha_n f_n, w^n}$ and find
  \begin{align*}
    I_{1,3} 
    &= \| (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) \|^2\\
    &=  \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
    \|\iota \nabla f_n(w^n)\| )^2}.
  \end{align*}
  Thus, for $I_1$, we have
  \begin{align*}
    I_1
    \leq \Big( 1 - \frac{2 \alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } 
    \Big)\| w^n - w^*\|^2
    + \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
      \|\iota \nabla f_n(w^n)\| )^2}.
  \end{align*}
  Further, $I_2$ can be written as
  \begin{align*}
    I_2
    = \|T_{\alpha_n f_n, w^n}(w^*) - w^*\|^2
    = \frac{\alpha_n^2 \|\iota \nabla f_n (w^*)\|^2 }{( 1 + \alpha_n \|\iota \nabla 
      f_n(w^n)\| )^2}.
  \end{align*}
  Finally, $I_3$ can be rewritten as
  \begin{align*}
    I_3 &= \dual{T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)}{T_{\alpha_n f_n, 
        w^n}(w^*) - w^*}\\
    &= \dual{(T_{\alpha_n f_n, w^n} - I) (w^n) - (T_{\alpha_n f_n, w^n} - I) 
      (w^*)}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &\quad + \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}
    =: I_{3,1} + I_{3,2}.
  \end{align*}
  Then for $I_{3,1}$, we insert the definition of $T_{\alpha_n f_n, w^n}$ and obtain
  \begin{align*}
    I_{3,1} &= \dual{(T_{\alpha_n f_n, w^n} - I) (w^n) - (T_{\alpha_n f_n, w^n} - I) 
      (w^*)}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &\leq \frac{\alpha_n \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|}{1 + \alpha_n \|\iota 
    \nabla f_n(w^n)\|} \cdot
    \frac{\alpha_n \| \iota \nabla f_n (w^*)\|}{1 + \alpha_n \|\iota \nabla f_n(w^n)\|} \\
    &\leq \frac{1}{2}\frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2}{ (1 + 
    \alpha_n \|\iota \nabla f_n(w^n)\| )^2} 
    + \frac{1}{2} \frac{\alpha_n^2 \| \iota \nabla f_n (w^*)\|^2}{(1 + \alpha_n \|\iota 
      \nabla f_n(w^n)\| )^2},
  \end{align*}
  where we applied the Cauchy--Schwarz inequality and Young's inequality.
  To estimate $I_{3,2}$, we add and subtract an additional summand, so that
  \begin{align*}
    I_{3,2} &= \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
    &= \dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
    f_n(w^*)}{1 + \alpha_n \Xi }}
    - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \Xi }},
  \end{align*}
  where $\E_{\xi_n}\big[ \dualb{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 
  + \alpha_n \Xi }} \big] = 0$ is fulfilled. Moreover, applying 
  Lemma~\ref{lem:SecondLipT} and the Cauchy--Schwarz inequality, we obtain
  \begin{align*}
    &\dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
        f_n(w^*)}{1 + \alpha_n \Xi }}\\
    &\leq \frac{ \alpha_n^2 \big|\Xi - \|\iota \nabla f_n(w^n)\| \big| \|\iota \nabla f_n(w^*)\|}
    {(1 + \alpha_n \|\iota \nabla f_n(w^n)\| ) (1 + \alpha_n \Xi )}  \| w^n 
    - w^* \|.
  \end{align*}
  Thus, the expectation of $I_3 = I_{3,1} + I_{3,2}$ can be bounded by
  \begin{align*}
    \E_{\xi_n} [I_3 ]
    &\leq \frac{1}{2} \E_{\xi_n} \Big[ \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla 
    f_n(w^*)\|^2 }{\big(1 + \alpha_n \|\iota \nabla 
      f_n(w^n)\|\big)^2} + \frac{\alpha_n^2 \| \iota \nabla f_n 
      (w^*)\|^2}{ (1 + \alpha_n \|\iota \nabla f_n(w^n)\| )^2}\Big]\\
    &\quad + \E_{\xi_n} \Big[ \frac{ \alpha_n^2 \big| \Xi - \|\iota \nabla f_n(w^n)\| \big| \|\iota 
    \nabla f_n(w^*)\| }
    {(1 + \alpha_n \|\iota \nabla f_n(w^n)\| ) (1 + \alpha_n \Xi )}\Big]  \| w^n - w^* \| .
  \end{align*}
  Inserting the bounds for $I_1$, $I_2$ and $I_3$ into $\E_{\xi_n} \big[\| w^{n+1} - w^* 
  \|^2\big] = \E_{\xi_n} \big[ I_1 + I_2 + 2 I_3\big]$ finishes the proof.
\end{proof}

The term $I_{1,2}$ can be estimated by applying the Cauchy--Schwarz inequality:
\begin{align*}
  I_{1,2}&= \dualb{w^n - w^*}{ (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - 
    I)(w^*) }\\
  &= - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^n)}{1 + \alpha_n \|\iota 
  \nabla f_n(w^n)\|} 
    - \frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \|\iota \nabla f_n(w^n)\|}}\\
  &\leq - \frac{\alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } \|w^n - 
  w^*\|^2.
\end{align*}

For $I_{1,3}$, we insert the definition of $T_{\alpha_n f_n, w^n}$ and find
\begin{align*}
  I_{1,3} 
  &= \| (T_{\alpha_n f_n, w^n} - I)(w^n) - (T_{\alpha_n f_n, w^n} - I)(w^*) \|^2\\
  &=  \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
  \|\iota \nabla f_n(w^n)\| )^2}.
\end{align*}

Thus, for $I_1$, we have
\begin{align*}
  I_1
  \leq \Big( 1 - \frac{2 \alpha_n \mu_{\xi_n} }{1 + \alpha_n \|\iota \nabla f_n(w^n)\| } 
  \Big)\| w^n - w^*\|^2
  + \frac{\alpha_n^2 \|\iota \nabla f_n(w^n) - \iota \nabla f_n(w^*)\|^2 }{ (1 + \alpha 
    \|\iota \nabla f_n(w^n)\| )^2}.
\end{align*}

Finally, $I_3$ can be rewritten as
\begin{align*}
  I_3 &= \dual{T_{\alpha_n f_n, w^n}(w^n) - T_{\alpha_n f_n, w^n}(w^*)}{T_{\alpha_n f_n, 
      w^n}(w^*) - w^*}\\
  &= \dual{(T_{\alpha_n f_n, w^n} - I) (w^n) - (T_{\alpha_n f_n, w^n} - I) 
    (w^*)}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
  &\quad + \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}
  =: I_{3,1} + I_{3,2}.
\end{align*}

To estimate $I_{3,2}$, we add and subtract an additional summand, so that
\begin{align*}
  I_{3,2} &= \dual{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*)}\\
  &= \dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
  f_n(w^*)}{1 + \alpha_n \Xi }}
  - \dualB{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 + \alpha_n \Xi }},
\end{align*}
where $\E_{\xi_n}\big[ \dualb{w^n - w^*}{\frac{\alpha_n \iota \nabla f_n(w^*)}{1 
+ \alpha_n \Xi }} \big] = 0$ is fulfilled. Moreover, applying 
Lemma~\ref{lem:SecondLipT} and the Cauchy--Schwarz inequality, we obtain
\begin{align*}
  &\dualB{w^n - w^*}{(T_{\alpha_n f_n, w^n} - I) (w^*) + \frac{\alpha_n \iota \nabla 
      f_n(w^*)}{1 + \alpha_n \Xi }}\\
  &\leq \frac{ \alpha_n^2 \big|\Xi - \|\iota \nabla f_n(w^n)\| \big| \|\iota \nabla f_n(w^*)\|}
  {(1 + \alpha_n \|\iota \nabla f_n(w^n)\| ) (1 + \alpha_n \Xi )}  \| w^n 
  - w^* \|.
\end{align*}

\begin{proof}
  In this proof, we apply the following basic inequalities involving (generalized) 
  harmonic numbers
  \begin{align*}
    \sum_{i=m}^n (i+y)^{-1} &\geq \ln{(n+1+y)} - \ln{(m+y)}, 
    \quad m \in \{1,\dots,n\},\\
    \sum_{i=1}^n{ (i+y)^{p}}
    &\leq 
    \begin{cases}
      \frac{(n+1+y)^{p+1}}{p+1}, &p \in [0,\infty) ,\\
      \frac{(n+y)^{p+1}}{p+1}, &p \in (-1,0),\\
      1 + \ln{(n+y)}, &p = -1,\\
      \frac{(1+y)^{p}(p-y)}{p+1}, &p \in (-\infty,-1),
    \end{cases}
  \end{align*}
  for $y \in (0,\infty)$.
  These inequalities follow by treating the sums as a lower or upper Riemann 
  sums approximating the integral $\int {(u+y)^p \diff{u}}$ over the intervals $[0,n]$, $[1,n]$ 
  or $[0,n+1]$. 

  Using the inequality $1 + u \le \exp{u}$ for $u \in [-1, \infty)$, it follows that $0\leq 
  1-\frac{x}{i + y} \le \exptext{-\frac{x}{i+y}}$ is fulfilled for every $i \in \N$ since 
  $\frac{x}{1+y} \leq 1$. It then follows that
  \begin{align*}
    \prod_{i= m}^n \Big(1- \frac{x }{i + y}\Big) 
    &\leq \exptextB{- x \sum_{i=m}^{n} (i + y)^{-1}} \\
    &\leq \exptextb{- x \big(\ln{(n+1+y)} - \ln(m+y)\big)} \\
    &= \exptextB{- x \ln{\Big(\frac{n+1+y}{m+y} \Big)} } 
    = \Big(\frac{n+1+y}{m+y} \Big)^{-x}
  \end{align*}
  from which the first claim follows directly. 
  For the second claim, we use the fact that $\frac{i+1+y}{i+y} = 1 + \frac{1}{i+y} \leq  1 + 
  \frac{1}{1+y}
  \leq \exptext{\frac{1}{1+y}}$ for all $i \in \N$ and find that
  \begin{align*}
    &\sum_{i=1}^n \frac{1}{(i+y)^2} \prod_{j = i+1}^n \Big(1-\frac{x}{j+y} 
    \Big)
    \le \sum_{i=1}^n { \frac{1}{(i+y)^2} \Big(\frac{n+1+y}{i+1+y}\Big)^{-x} } \\
    &\le (n+1+y)^{-x} \sum_{i=1}^n{ \Big(\frac{i+1+y}{i+y}\Big)^{x} (i+y)^{x-2} }\\
    &\le  \exptextB{\frac{x}{1+y}} (n+1+y)^{-x} 
    \sum_{i=1}^n{ (i+y)^{x-2} }\\
    &\leq \exptextB{\frac{x}{1+y}}
    \begin{cases}
      (n+1+y)^{-1}\frac{1}{x-1}, &x \in (1,\infty) ,\\
      (n+1+y)^{-1} \big(1 + \ln{(n+y)}\big), &x = 1,\\
      (n+1+y)^{-x}\frac{(1+y)^{x-2}(x-2-y)}{x-1}, 
      &x \in [0,1),
    \end{cases}
  \end{align*}
  where we applied the basic inequalities from the beginning of the proof.
\end{proof}

